<x-layouts.app title="Banca {{ $banca->numero }} — Sistema del Recinto">
    <div x-data="bancaRecinto()" x-init="cargar()" @recinto-resync.window="cargar()" class="space-y-5">
        <header class="rounded-2xl bg-slate-950 p-6 text-white"><div class="flex items-center justify-between"><div><p class="text-sm font-bold uppercase tracking-widest text-sky-400">Banca {{ $banca->numero }}</p><h1 class="mt-2 text-3xl font-black">{{ $legislador->nombre }}</h1></div><span class="rounded-full px-4 py-2 text-sm font-black" :class="estado.habilitada ? 'bg-emerald-500' : 'bg-red-600'" x-text="estado.habilitada ? 'HABILITADA' : 'NO HABILITADA'"></span></div></header>
        <section x-show="estado.votacion" class="rounded-2xl bg-white p-6 shadow-xl ring-2 ring-sky-500"><p class="text-sm font-bold uppercase tracking-widest text-sky-700">Votación directa</p><h2 class="mt-2 text-2xl font-black" x-text="estado.votacion?.tema"></h2><p class="mt-2 text-slate-500">Puede corregir el voto mientras la votación permanezca abierta.</p><div class="mt-6 grid gap-4 md:grid-cols-3"><template x-for="opcion in opciones"><button @click="votar(opcion.valor)" :disabled="enviando || !estado.habilitada" class="min-h-28 rounded-2xl text-xl font-black text-white disabled:opacity-40" :class="[opcion.clase, estado.votacion?.voto === opcion.valor ? 'ring-4 ring-offset-4 ring-sky-400' : '']" x-text="opcion.texto"></button></template></div><p class="mt-5 text-center text-lg font-bold" x-text="restante"></p></section>
        <section x-show="estado.documento" class="overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-slate-200"><div class="flex items-center justify-between p-4"><strong x-text="estado.documento?.titulo"></strong><a :href="estado.documento?.url" target="_blank" class="rounded-lg bg-slate-100 px-4 py-2 font-bold">Abrir</a></div><iframe :src="estado.documento?.url" class="h-[70vh] w-full border-t" title="Documento de la sesión"></iframe></section>
        <section x-show="!estado.activa" class="rounded-2xl border-2 border-dashed p-12 text-center"><h2 class="text-2xl font-black">Esperando el inicio de la sesión</h2></section>
    </div>
    <script>function bancaRecinto(){return {estado:{},enviando:false,restante:'',opciones:[{valor:'afirmativo',texto:'AFIRMATIVO',clase:'bg-emerald-600'},{valor:'negativo',texto:'NEGATIVO',clase:'bg-red-600'},{valor:'abstencion',texto:'ABSTENCIÓN',clase:'bg-amber-500'}],async cargar(){const r=await axios.get('{{ route('bancas.estado',$banca) }}');this.estado=r.data;this.actualizarTiempo()},actualizarTiempo(){if(!this.estado.votacion?.finaliza_en){this.restante='';return}const s=Math.max(0,Math.ceil((new Date(this.estado.votacion.finaliza_en)-new Date())/1000));this.restante=`Tiempo restante: ${s} s`;if(s>0)setTimeout(()=>this.actualizarTiempo(),1000);else this.cargar()},async votar(opcion){this.enviando=true;try{await axios.put(`/bancas/{{ $banca->id }}/votaciones/${this.estado.votacion.id}/voto`,{opcion});await this.cargar()}finally{this.enviando=false}}}}</script>
</x-layouts.app>
